              "Sie behalten Ihre Rechte an Ihren Dokumenten, Präsentationen und Inhalten. Um eine von Ihnen aktiv gestartete Übersetzungsanfrage auszuführen, autorisieren Sie TransLay, auf die ausgewählte Datei zuzugreifen, den zu übersetzenden Text zu lesen, die Übersetzung zu erzeugen und das Ergebnis gemäß Ihren Anweisungen in die Originaldatei oder eine neue Zieldatei zurückzuschreiben. Diese Autorisierung dient ausschließlich der Bereitstellung des Dienstes und überträgt kein Eigentum an Ihren Inhalten auf uns.",
              "Text, Übersetzungen, Comments und Notes werden nur kurz während der Ausführung verarbeitet. Sobald die Aufgabe endet, werden diese Inhalte aus unserer Datenbank und unserem Cache gelöscht und nicht als Cloud-Backup aufbewahrt. Bitte bewahren Sie Ihre übersetzten Dateien selbst auf. Wenn Sie dasselbe Dokument später erneut in dieselbe Sprache übersetzen lassen möchten, behandeln wir dies als neue unabhängige Aufgabe und berechnen sie vollständig."
