              "Você mantém todos os direitos sobre seus documentos, apresentações e respectivos conteúdos. Para concluir uma solicitação de tradução iniciada por você, você autoriza o TransLay, no escopo necessário para operar o serviço, a acessar o arquivo selecionado, ler o conteúdo a ser traduzido, gerar a tradução e gravar o resultado no documento original ou em um novo documento de destino conforme suas instruções. Essa autorização existe apenas para prestar o serviço e não transfere a nós a propriedade do seu conteúdo.",
