              "Somente depois que você inicia ativamente uma tarefa de tradução, processamos o conteúdo do Google Slides™ que você escolheu explicitamente traduzir, apenas para concluir essa tradução e gravar o resultado.",
              "Também processamos as informações mínimas de tarefa e créditos necessárias para exibir progresso, liquidar créditos, verificar problemas de cobrança e oferecer suporte, como Task ID, status da tarefa, uso de páginas, timestamps e metadados limitados de diagnóstico.",
              "Se você comprar um plano ou créditos, processamos as informações mínimas de pedido e assinatura necessárias para confirmar seus benefícios, como status de pagamento, número do pedido, horário de compra ou reembolso e status da assinatura. Dados completos de cartão são processados pela Paddle e não são salvos por nós.",
              "Para sessões do site, usamos apenas as informações mínimas necessárias para manter o site oficial e as páginas de assinatura funcionando. O cookie guarda apenas um session id opaco e não salva diretamente seu email, plano, cota ou outras informações legíveis."
