              "Se depois você iniciar outra tradução do mesmo documento para o mesmo idioma, trataremos isso como uma nova tarefa independente. Como não mantemos o conteúdo ou a tradução anterior, essa tarefa não reutilizará diretamente o resultado anterior e será cobrada integralmente conforme as regras da tarefa atual.",
              "Não usamos suas informações para publicidade, atribuição de anúncios, criação de perfil de usuário ou análise comportamental. Não vendemos seus dados e não rastreamos seu comportamento em outros sites, documentos ou produtos pelo fato de você usar o TransLay.",
              "Não salvamos seu número completo de cartão, número completo de conta bancária ou outras credenciais completas de pagamento. Pagamentos são processados pela Paddle; recebemos apenas as informações mínimas necessárias para pedidos e suporte pós-venda."
