              "För webbplatssessioner använder vi bara den minsta sessionsinformation som krävs för att den officiella webbplatsen och prenumerationssidorna ska fungera. Cookies sparar endast ett opakt session-id och sparar inte direkt läsbar klartext som e-postadress, plan eller kvot."
