      title: "知りたいことをまとめました。",
      q1: "TransLay はどうやってインストールしますか？",
      a1: "Google Workspace Marketplace で「TransLay」を検索し、インストールをクリックします。Google Slides™ の権限を許可すると、任意のプレゼンテーション内の 拡張機能 → TransLay から利用できます。",
